  "PROP-6a4369e9-inv-047": {
    "property_id": "PROP-6a4369e9-inv-047",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-047",
      "classification": "vulnerability",
      "code_path": "beacon_chain/spec/peerdas_helpers.nim::handle_custody_groups::L50-65",
      "proof_trace": "The while loop at line 50 terminates only when HashSet size equals custody_group_count. However, all inserted elements are bounded by mod NUMBER_OF_CUSTODY_GROUPS (line 58-59), so the set saturates at 128 elements. When peer-reported custody_group_count > 128, the loop condition can never be satisfied, causing an infinite loop.",
      "attack_scenario": "Malicious peer advertises custody_group_count = 2^32 via P2P metadata. When victim calls checkPeerCustody or matchIntersection during data column sync, handle_custody_groups enters infinite loop, freezing the requesting thread and causing DoS.",
      "checklist_id": "PROP-6a4369e9-inv-047"
    },
    "text": "Peer-reported custody_group_count must be validated against NUMBER_OF_CUSTODY_GROUPS upper bound before use in any loop or data structure sizing. handle_custody_groups must terminate in O(NUMBER_OF_CUSTODY_GROUPS) iterations regardless of the peer-advertised value.",
    "assertion": "forall peer_cgc: handle_custody_groups(peer_cgc, ...) terminates AND iterations <= NUMBER_OF_CUSTODY_GROUPS, even when peer_cgc > NUMBER_OF_CUSTODY_GROUPS",
    "covers": "SG-006",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

  # is assumed.

  let metadata = peer.metadata
  if metadata.isOk:
    return metadata.get.custody_group_count

  # Try getting the custody count from ENR if metadata fetch fails.
  debug "Could not get cgc from metadata, trying from ENR",
        peer_id = peer.peerId
  let enrOpt = peer.enr
  if not enrOpt.isNone:
    let enr = enrOpt.get
    let enrFieldOpt = enr.get(enrCustodySubnetCountField, seq[byte])
    if enrFieldOpt.isOk:
      try:
        let cgc = SSZ.decode(enrFieldOpt.get, uint8)
        return cgc.uint64
      except SszError, SerializationError:
        discard  # Ignore decoding errors and fallback to default

  # Return default value if no valid custody subnet count is found.
  return CUSTODY_REQUIREMENT.uint64

